"""Abstract base interface for AgentBreaker report generators."""

from abc import ABC, abstractmethod

from agentbreaker.reporting.models import AssessmentReport, ReportFormat


class BaseReportGenerator(ABC):
    """Abstract base class defining report generator interface."""

    @property
    @abstractmethod
    def report_format(self) -> ReportFormat:
        """The output format generated by this class."""

    @abstractmethod
    def generate(self, report: AssessmentReport) -> str:
        """Render the structured assessment report into the target output format."""
